import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"快速上手","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/getting-started.md","filePath":"zh-HK/user-guide/getting-started.md","lastUpdated":1787982919000}'),l={name:"zh-HK/user-guide/getting-started.md"};function d(n,t,i,s,c,g){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h1><p>歡迎使用 Lertaro！Lertaro 是一款為 Windows 深度定制的極速檔案檢索與生產力啟動器。本章將帶你了解安裝方式、核心架構、三種視窗形態以及基本的日常搜尋操作。</p><h2 id="_1-下載與安裝" tabindex="-1">1. 下載與安裝 <a class="header-anchor" href="#_1-下載與安裝" aria-label="Permalink to &quot;1. 下載與安裝&quot;">​</a></h2><p>你可以在官方網站首頁獲取最新版本。每個正式發佈版本均提供安裝包和便攜版，並分別包含原生 <strong>x64</strong> 與 <strong>ARM64</strong> 應用程式：</p><h3 id="安裝包-lertaro-setup-exe-推薦" tabindex="-1">安裝包（<code>Lertaro-Setup.exe</code>，推薦） <a class="header-anchor" href="#安裝包-lertaro-setup-exe-推薦" aria-label="Permalink to &quot;安裝包（`Lertaro-Setup.exe`，推薦）&quot;">​</a></h3><ul><li><strong>自動化設定</strong>：安裝精靈會自動註冊後台索引服務（<code>Lertaro.Service</code>），設定開機自啟動項，並自動偵測與安裝所需的 .NET 桌面執行階段。</li><li><strong>平滑升級</strong>：支援靜默自動檢查更新與一鍵覆蓋升級。</li></ul><h3 id="便攜版-lertaro-portable-zip" tabindex="-1">便攜版（<code>Lertaro-Portable.zip</code>） <a class="header-anchor" href="#便攜版-lertaro-portable-zip" aria-label="Permalink to &quot;便攜版（`Lertaro-Portable.zip`）&quot;">​</a></h3><ul><li><strong>解壓即用</strong>：解壓至任意目錄即可直接運行主程式，不強制要求安裝。</li><li><strong>環境補齊</strong>：若系統尚未安裝對應的 .NET 桌面執行階段，可直接運行解壓目錄自帶的 <code>install-dotnet-runtime.bat</code> 腳本一鍵安裝。</li><li><strong>資料獨立與隔離</strong>：便攜版預設將機器全域資料儲存在程式同級目錄的 <code>Data\\Machine</code>，並將各用戶的私有設定儲存在 <code>Data\\Users\\&lt;SID hash&gt;</code>。若該 <code>Data</code> 目錄尚未建立，會自動兼容讀取系統的 <code>%ProgramData%\\Lertaro</code> 和 <code>%LocalAppData%\\Lertaro</code>；一旦目錄生成，便攜版將優先讀取本地獨立資料，實現完全自包含。</li><li><strong>乾淨解除安裝與清理</strong>：當不再需要使用便攜版時，在刪除資料夾前請先執行自帶的 <code>portable-cleanup.bat</code> 腳本。該腳本會自動停止並解除安裝後台服務，並清理當前用戶的 <code>lertaro://</code> URI 協議及自啟註冊表項。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>如果你在 Windows on ARM 裝置（如 Surface Pro X、高通驍龍筆記本）上運行，請優先下載 <code>Lertaro-Setup-arm64.exe</code> 或 <code>Lertaro-Portable-arm64.zip</code> 原生版本，以獲得最佳效能與更低的功耗。</p></div><h2 id="_2-核心架構認知" tabindex="-1">2. 核心架構認知 <a class="header-anchor" href="#_2-核心架構認知" aria-label="Permalink to &quot;2. 核心架構認知&quot;">​</a></h2><p>首次運行 Lertaro 時，系統會安裝並啟動一個獨立的 Windows 後台服務（<code>Lertaro.Service</code>）。理解該設計有助於你更好地掌握其運作原理：</p><ul><li><strong>前台 App（UI 與互動層）</strong>：負責渲染搜尋視窗、懸浮面板、動作選單、快捷鍵攔截與即時預覽。前台程序始終保持極低記憶體佔用與即時回應。</li><li><strong>後台 Service（索引與資料層）</strong>：以系統服務權限在後台運行，專門負責讀取 NTFS / ReFS 的 USN 記錄檔、監聽其他檔案系統的即時變動、維護網路共用索引，並建立極速記憶體索引樹。</li><li><strong>架構優勢</strong>：前台介面的重啟、當機或更新絕不會導致後台索引遺失或重新全盤掃描；而後台的即時索引同步也絕不會阻塞前台 UI 的流暢打字體驗。你可以在<a href="./settings/service-status.html"><strong>設定 → 運行狀態</strong></a>中隨時查看服務運行狀態與索引健康度。</li></ul><h2 id="_3-三種視窗形態" tabindex="-1">3. 三種視窗形態 <a class="header-anchor" href="#_3-三種視窗形態" aria-label="Permalink to &quot;3. 三種視窗形態&quot;">​</a></h2><p>Lertaro 並非只有一個固定的搜尋視窗，而是針對不同工作流設計了三種各具特色的視窗形態：</p><table tabindex="0"><thead><tr><th style="text-align:left;">視窗形態</th><th style="text-align:left;">預設喚起方式</th><th style="text-align:left;">核心特點與設計定位</th><th style="text-align:left;">適用場景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>快速視窗（Quick Window）</strong></td><td style="text-align:left;">雙擊 <code>Ctrl</code>（可自訂）</td><td style="text-align:left;">緊湊型螢幕置中浮窗，即輸即搜，肌肉記憶友好，支援數字鍵快速跳轉與全鍵盤流操作</td><td style="text-align:left;">日常高頻啟動應用程式、尋找特定檔案、快速計算或翻譯</td></tr><tr><td style="text-align:left;"><strong>主視窗（Full Window）</strong></td><td style="text-align:left;">工作列/開始功能表，或快捷鍵 <code>Ctrl+F</code></td><td style="text-align:left;">完整的大尺寸視窗，支援海量結果表格檢視、側邊欄進階篩選、欄排序與內建空間分析器</td><td style="text-align:left;">深度檔案瀏覽、大範圍檢索、磁碟空間清理與進階篩選</td></tr><tr><td style="text-align:left;"><strong>內嵌視窗（Inline Window）</strong></td><td style="text-align:left;">開啟檔案對話方塊或檔案總管時自動嵌入</td><td style="text-align:left;">無縫內嵌到系統檔案對話方塊或第三方管理器中，無需離開當前工作上下文</td><td style="text-align:left;">在 Office/瀏覽器等軟體中「開啟」或「另存為」檔案時快速定位目標</td></tr></tbody></table><p>三種視窗形態底層共享完全相同的搜尋引擎、快捷鍵體系、篩選規則與動作選單。</p><h2 id="_4-首次搜尋與基本互動" tabindex="-1">4. 首次搜尋與基本互動 <a class="header-anchor" href="#_4-首次搜尋與基本互動" aria-label="Permalink to &quot;4. 首次搜尋與基本互動&quot;">​</a></h2><h3 id="即輸即搜" tabindex="-1">即輸即搜 <a class="header-anchor" href="#即輸即搜" aria-label="Permalink to &quot;即輸即搜&quot;">​</a></h3><p>開啟搜尋視窗後直接輸入關鍵字即可，結果將隨輸入即時呈現（毫秒級回應）。搜尋演算法預設採用智慧模糊比對，字元無需連續輸入即可跳躍命中。詳細比對規則與修飾符請參閱<a href="./search-syntax.html"><strong>搜尋語法</strong></a>。</p><h3 id="結果導覽與開啟" tabindex="-1">結果導覽與開啟 <a class="header-anchor" href="#結果導覽與開啟" aria-label="Permalink to &quot;結果導覽與開啟&quot;">​</a></h3><ul><li><strong>移動游標</strong>：使用方向鍵 <code>↑</code> / <code>↓</code>（或設定的導覽快捷鍵 <code>Ctrl+P</code> / <code>Ctrl+N</code>）在結果列表中上下移動選取項目。</li><li><strong>直接開啟</strong>：按下 <code>Enter</code> 立即使用預設程式開啟選取的檔案或啟動應用程式。</li><li><strong>定位目錄</strong>：按下 <code>Ctrl+Enter</code> 可在檔案總管中直接定位並選取該檔案。</li><li><strong>系統管理員身分運行</strong>：按下 <code>Ctrl+Shift+Enter</code> 以系統管理員權限運行程式。</li><li><strong>數字直達</strong>：在快速視窗中，可直接按下 <code>Ctrl</code> + <code>1</code>–<code>9</code> 直接開啟前 9 項結果。</li></ul><h3 id="動作選單與擴充操作" tabindex="-1">動作選單與擴充操作 <a class="header-anchor" href="#動作選單與擴充操作" aria-label="Permalink to &quot;動作選單與擴充操作&quot;">​</a></h3><p>按下 <code>Ctrl+O</code> 或在選取項目上按方向鍵 <code>→</code>，即可展開功能強大的<strong>動作選單</strong>，執行複製路徑、屬性查看、檔案增刪剪貼或呼叫外掛模組擴充動作。更多操作技巧請閱讀<a href="./actions-and-preview.html"><strong>動作選單與預覽</strong></a>與<a href="./hotkeys.html"><strong>熱鍵</strong></a>。</p>',23)])])}const p=e(l,[["render",d]]);export{u as __pageData,p as default};
